```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> dane;
    int x;
    while (plik >> x) dane.push_back(x);
    int maxEnd = 0, maxSoFar = dane[0];
    int start = 0, end = 0, tempStart = 0;
    for (int i = 0; i < (int)dane.size(); i++) {
        maxEnd += dane[i];
        if (maxEnd > maxSoFar) {
            maxSoFar = maxEnd;
            start = tempStart;
            end = i;
        }
        if (maxEnd < 0) {
            maxEnd = 0;
            tempStart = i + 1;
        }
    }
    cout << "Max suma spojnego podciagu: " << maxSoFar << endl;
    cout << "Od pozycji " << start + 1 << " do " << end + 1 << endl;
    cout << "Elementy:";
    for (int i = start; i <= end; i++) {
        cout << " " << dane[i];
    }
    cout << endl;
    return 0;
}
```

Weryfikacja:
- Podciag od pos 2 do 10: 3+5-1+4-7+2+8-3+6 = 17
- Sprawdzenie: 3+5=8, -1→7, +4=11, -7→4, +2=6, +8=14, -3→11, +6=17
- Alternatywy: caly ciag: -2+3+5-1+4-7+2+8-3+6-4+1 = 12 (mniej)
- Podciag jest optymalny: suma 17
